const $=id=>document.getElementById(id),canvas=$('game'),ctx=canvas.getContext('2d'),overlay=$('overlay'),audio=new MusicAudio(),SAVE='b3pz-tour-v1';
const W=960,H=600,T=24,keys=new Set();let state=initialState(),saved=null,mode='world',area='town',road=null,objects=[],solids=[],song=null,near=null,last=performance.now(),walk=0,toastTimer,puzzleTimers=[],path=[],tapObject=null;
