function syncAudio(){audio.volume=state.settings.volume;audio.muted=state.settings.muted;audio.update();$('soundBtn').textContent=audio.muted?'OFF ♫':'ON ♪';}
function save(){try{localStorage.setItem(SAVE,JSON.stringify(state));$('saveLabel').textContent='Partita salvata su questo dispositivo';}catch{$('saveLabel').textContent='Salvataggio non disponibile: esporta dal menu';}}
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3500);}
function clearPuzzleTimers(){puzzleTimers.forEach(clearTimeout);puzzleTimers=[];}
function panel(title,body,actions=[],tag='IL TACCUINO DELLA BAND'){
 keys.clear();path=[];tapObject=null;near=null;$('prompt').hidden=true;overlay.hidden=false;overlay.innerHTML='';const p=document.createElement('section');p.className='panel';p.setAttribute('role','dialog');p.setAttribute('aria-label',title);p.innerHTML=`<div class="eyebrow">${tag}</div><h3>${title}</h3>${body}<div class="actions"></div>`;overlay.appendChild(p);
 for(const a of actions){const b=document.createElement('button');b.className='btn'+(a.secondary?' secondary':'');b.textContent=a.label;b.addEventListener('click',a.run);p.querySelector('.actions').appendChild(b);}p.querySelector('button')?.focus();return p;
}
function close(){clearPuzzleTimers();overlay.hidden=true;overlay.innerHTML='';keys.clear();canvas.focus();}
function updateJournal(){
 const c=CITIES[state.city];$('location').textContent=area==='road'?`SENTIERO · ${CITIES[road.from].name.toUpperCase()} → ${CITIES[road.to].name.toUpperCase()}`:c.name.toUpperCase();$('season').textContent=`${month(state)} · ${state.passes.length} PASS`;$('sceneBadge').textContent=`${String(state.city+1).padStart(2,'0')} / ${area==='road'?'IN CAMMINO':c.genre.toUpperCase()}`;
 $('passCount').innerHTML=`${state.passes.length}<span>/8</span>`;$('passGrid').innerHTML=MUSIC_CITIES.map(c=>`<div class="stamp ${state.passes.includes(c.id)?'earned':''}" title="${c.genre}">${c.genre.slice(0,3).toUpperCase()}</div>`).join('');
 let objective=state.stage==='school'?'Ultimo giorno di scuola. Raggiungi la scuola a nord-est del paese.':state.stage==='practice'?'Gli amici ti aspettano nel garage, a ovest della piazza.':state.stage==='rival'?'La band rivale è in piazza. È ora della prima sfida.':state.finished?'Il festival è vostro. Puoi tornare nei luoghi del viaggio e suonare ancora.':state.passes.length===8&&!state.homeShow?'Torna a Borgo delle Cicale: il concerto a casa vi aspetta.':state.homeShow?'Raggiungi Settembre e sali sul palco del festival.':c.type==='music'&&!state.puzzles.includes(c.id)?`Trova ${c.teacher} in piazza e risolvi la prova di ${c.genre.toLowerCase()}.`:c.type==='music'&&!state.passes.includes(c.id)?'La prova è superata. Raggiungi il palco e conquista il pass.':'Esplora i sentieri e cerca altri musicisti. Otto città, otto pass.';
 $('objective').textContent=objective;$('instrumentTag').textContent=`${INSTRUMENTS[state.instrument].name.toUpperCase()} · ${state.bike?'IN BICICLETTA':state.bicycle?'BICI SBLOCCATA · B':'A PIEDI'} · LV ${1+Math.floor(state.xp/100)}`;
}
function welcome(){panel('Tutta l’estate davanti.',`<p>L’ultimo giorno di scuola. Una sala prove tra i campi. Tre amici che nessuno prende sul serio.</p><p>A settembre c’è un festival. Prima, c’è una strada intera da suonare.</p><p class="fine">Prototipo giocabile · 12 località compatte · Musica sintetizzata originale<br>Usa cuffie o altoparlanti. Nessuna registrazione del microfono.</p>`,[...(saved?[{label:'Continua il viaggio',run:()=>{state=saved;syncAudio();setupTown();close();}}]:[]),{label:saved?'Nuova estate':'Comincia il viaggio',run:()=>saved?panel('Una nuova estate?',`<p>La nuova partita sostituirà il salvataggio su questo dispositivo. Puoi esportarlo prima dalle impostazioni.</p>`,[{label:'Scegli lo strumento',run:chooseInstrument},{label:'Indietro',run:welcome,secondary:true}]):chooseInstrument()}], 'GIUGNO / PRIMA CHE COMINCI TUTTO');}
function chooseInstrument(){const p=panel('Qual è il tuo suono?',`<p>Lo strumento che porti con te cambia tutte le prove musicali. Gli amici suoneranno le altre due parti.</p><div class="instrument-choices"></div><p class="fine">Quattro tasti, tre modi diversi di suonare. Su telefono usa i pulsanti sullo schermo.</p>`,[],'TRE STRUMENTI. UNA BAND.');
 for(const [id,data]of Object.entries(INSTRUMENTS)){const b=document.createElement('button');b.className='instrument-card';b.innerHTML=`<span class="instrument-art">${id==='guitar'?'♮':id==='bass'?'♩':'◉'}</span><b>${data.name}</b><small>${data.role}</small>`;b.onclick=async()=>{state=initialState(id);syncAudio();try{await audio.init();audio.note(id,0,110,audio.ctx.currentTime);}catch{}setupTown();save();panel('Oggi finisce la scuola.',`<p>«Ti aspettiamo nel pomeriggio. Ho trovato un posto per provare!»</p><p>Nico e Vale hanno lasciato un biglietto sul cancello. Prima però c’è l’ultima mattinata di scuola.</p><p class="fine">Muoviti con WASD / frecce. Avvicinati a porte e persone, poi premi E o PARLA / USA. La scuola è a nord-est.</p>`,[{label:'Esci di casa',run:close}],'BORGO DELLE CICALE / ORE 08:00');};p.querySelector('.instrument-choices').appendChild(b);}p.querySelector('button')?.focus();}
function building(x,y,w,h,label,kind){solids.push({x,y,w,h});objects.push({x:x+w/2,y:y+h+.7,label,kind,building:{x,y,w,h,label}});}
function setupTown(){area='town';road=null;path=[];tapObject=null;objects=[];solids=[];const c=CITIES[state.city];
 building(7,7,7,5,state.city===0?'CASA':'BOTTEGA','house');building(29,7,10,5,state.city===0?'SCUOLA':c.type==='story'?'ARCHIVIO':'SALA MUSICA',state.city===0?'school':'lore');building(7,19,8,5,state.city===0?'GARAGE':'SALA PROVE','garage');
 objects.push({x:29,y:22,label:c.type==='music'?c.teacher:state.city===0?'Nico e Vale':state.city===11?'Organizzatrice':'Viaggiatore',kind:'npc',color:'#c99b66'});
 objects.push({x:35,y:21,label:state.city===0?'Palco della piazza':state.city===11?'Palco del festival':'Palco '+c.genre,kind:'stage'});
 objects.push({x:23,y:15,label:'Bacheca della tournée',kind:'board'});
 neighbors(state.city).forEach((id,i)=>{objects.push({x:43,y:15+i*3.8,label:(state.city===8&&id===9?'Imbarco → ':'Sentiero → ')+CITIES[id].name,kind:'exit',to:id});});
 state.x=Math.max(3,Math.min(44,state.x));state.y=Math.max(8,Math.min(29,state.y));updateJournal();}
function enterCity(id){state.city=id;state.x=23;state.y=23;if(!state.visited.includes(id))state.visited.push(id);setupTown();save();toast(CITIES[id].name+' · '+CITIES[id].genre);}
function startRoad(to){const reason=gate(state,to);if(reason){toast(reason);return;}if(state.city===8&&to===9&&!state.boat){panel('Un passaggio sul mare.',`<p>«Ci manca il gruppo di apertura. Suonate sul ponte e vi portiamo all’isola.»</p><p>Una traversata, un concerto. Il vostro primo pubblico in mezzo al mare.</p>`,[{label:'Sali sulla nave',run:()=>songBrief(8,'boat')},{label:'Resta al porto',run:close,secondary:true}],'PORTO DEL SOL / LA NAVE CONCERTO');return;}
 road={from:state.city,to};area='road';objects=[{x:4,y:20,label:'Ritorna a '+CITIES[state.city].name,kind:'roadBack'},{x:62,y:20,label:'Arriva a '+CITIES[to].name,kind:'roadEnd'},{x:23,y:17,label:'Musicista in viaggio',kind:'wanderer',color:'#9b8cb0'},{x:46,y:23,label:'Un messaggio sul sentiero',kind:'sign'}];solids=[];state.x=6;state.y=20;updateJournal();close();}
function interact(){if(mode!=='world'||!overlay.hidden)return;if(!near){toast('Avvicinati a una porta, a un musicista o a un cartello.');return;}const o=near,c=CITIES[state.city];
 if(o.kind==='exit'){startRoad(o.to);return;}if(o.kind==='roadEnd'){enterCity(road.to);return;}if(o.kind==='roadBack'){enterCity(road.from);return;}
 if(o.kind==='school'){if(state.stage==='school'){state.stage='practice';save();updateJournal();panel('L’ultima campanella.',`<p>Nico: «Tre mesi senza compiti. È il momento giusto.»</p><p>Vale: «Mio nonno ci lascia usare il garage. Ho già portato un amplificatore.»</p><p>I ragazzi degli <strong>Alta Tensione</strong> vi sentono: «Una band, voi? Ci vediamo in piazza. Portate i tappi per le orecchie.»</p>`,[{label:'Andiamo in sala prove',run:close}],'SCUOLA / GIUGNO');}else panel('Buone vacanze.',`<p>Le finestre sono chiuse. Sulla bacheca c’è ancora la locandina del festival di settembre.</p>`,[{label:'Torna in strada',run:close}]);return;}
 if(o.kind==='garage'){if(state.stage==='school'){toast('Prima vai a scuola: gli amici sono già lì.');return;}songBrief(state.city,state.stage==='practice'?'tutorial':'practice');return;}
 if(o.kind==='house'){panel(state.city===0?'Il posto da cui siamo partiti.':'Una porta aperta.',`<p>${state.city===0?state.passes.length?'Sul tavolo ci sono le vostre locandine. «Vi ho sentiti alla radio del paese. Quando tornate a suonare qui?»':'Una merenda nello zaino, lo strumento pronto. Fuori cominciano a cantare le cicale.':'Il proprietario ti offre un bicchiere d’acqua e ti indica la piazza. «La musica la trovi sempre da quella parte.»'}</p>`,[{label:'Riparti',run:close}]);return;}
 if(o.kind==='board'){showMap();return;}
 if(o.kind==='stage'){
  if(state.city===0){if(state.stage==='rival')songBrief(0,'rival');else if(state.stage!=='tour')toast('Prima raggiungi gli amici in sala prove.');else if(state.passes.length===8)songBrief(0,'home');else panel('Il palco della prima volta.',`<p>Nico: «Quando torniamo, facciamo un concerto per tutti. Ma prima dobbiamo avere qualcosa da raccontare.»</p>`,[{label:'Riparti',run:close}]);}
  else if(c.type==='final'){const reason=gate(state,11);if(reason)toast(reason);else songBrief(11,'final');}
  else if(c.type==='music'){if(!state.puzzles.includes(c.id))toast(`Prima parla con ${c.teacher}: ti aspetta in piazza.`);else songBrief(c.id,'concert');}
  else songBrief(2,'practice');return;
 }
 if(o.kind==='npc'){
  if(state.city===0){if(state.stage==='rival')songBrief(0,'rival');else panel('Nico e Vale',`<p>${state.stage==='school'?'«Non fare tardi! La scuola è dall’altra parte della piazza.»':state.stage==='practice'?'«Il garage è pronto. Vieni a provare con noi!»':state.passes.length===8?'«Ci siamo. Prima suoniamo a casa. Poi andiamo a prenderci settembre.»':'«Ogni città ci ha insegnato qualcosa. E pensa che volevamo soltanto passare un pomeriggio in garage.»'}</p>`,[{label:'Ci vediamo sul palco',run:close}]);}
  else if(c.type==='music')showTeacher(c);
  else if(state.city===3){state.bicycle=true;if(!state.stories.includes(3)){state.stories.push(3);state.xp+=40;save();updateJournal();}panel('Una bici, mille strade.',`<p>«Questa era qui a prendere polvere. Gonfiate le gomme e portatela a vedere il mare.»</p><p>Bicicletta sbloccata. Premi B o il pulsante BICI per alternare camminata e pedalata.</p>`,[{label:'Grazie!',run:close}]);}
  else if(state.city===6)showArchive();else panel('Il festival di settembre',`<p>«Otto pass, una band e un brano da portare sul palco. Vi aspettavamo.»</p>`,[{label:'Verso il palco',run:close}]);return;
 }
 if(o.kind==='lore'){if(state.city===6)showArchive();else panel('Storie dietro le note.',`<p>${c.text||c.lesson}</p><p>Una locandina racconta la scena musicale del posto. Nel prototipo le storie locali sono ancora brevi: qui troveranno spazio persone, piccoli concerti e ritorni.</p>`,[{label:'Torna fuori',run:close}]);return;}
 if(o.kind==='wanderer'){panel('Ci facciamo una suonata?',`<p>«Sto andando a ${CITIES[road.to].name}. Prima di ripartire, proviamo questo giro insieme?»</p>`,[{label:'Suona insieme',run:()=>songBrief(CITIES[road.to].type==='music'?road.to:1,'practice')},{label:'Buon viaggio!',run:close,secondary:true}],'INCONTRO SUL SENTIERO');return;}
 if(o.kind==='sign')panel('Qualcuno è passato di qui.',`<p>«Non serve suonare più forte di tutti. Basta trovare qualcuno che abbia voglia di ascoltare.»</p><p>Più avanti, una freccia indica ${CITIES[road.to].name}. Le cicale accompagnano l’ultimo tratto di strada.</p>`,[{label:'Continua a camminare',run:close}]);
}
function showArchive(){if(!state.stories.includes(6)){state.stories.push(6);state.xp+=40;save();updateJournal();}panel('Il lato B della cassetta.',`<p>Dietro una fotografia trovate tre ragazzi, un garage e un palco di paese. Uno di loro è il vostro insegnante.</p><p>Vale: «Pensavo che i grandi fossero sempre stati grandi.»</p><p>Nel lato B c’è un’idea rimasta incompleta. La annotate nel taccuino, per il vostro prossimo pezzo.</p>`,[{label:'Portiamo avanti la storia',run:close}],'VALDACCORDO / UNA BAND PRIMA DI VOI');}
function showTeacher(c){if(state.puzzles.includes(c.id)){panel(c.teacher+' · '+c.genre,`<p>«${c.lesson}»</p><p>Hai superato la prova. ${state.passes.includes(c.id)?'Il tuo pass è nel taccuino. Il palco è sempre aperto per una nuova esibizione.':'Il palco è pronto: conquistati il pass del locale.'}</p>`,[{label:'Ripassa la sequenza',run:()=>startPuzzle(c)},{label:'Torna in piazza',run:close,secondary:true}]);}else panel(c.teacher+' · Ascolta prima di suonare.',`<p>«${c.lesson}»</p><p>Prima del concerto, riproduci una breve frase su quattro note. Puoi ascoltarla e leggere gli indizi tutte le volte che vuoi.</p>`,[{label:'Comincia la prova',run:()=>startPuzzle(c)},{label:'Più tardi',run:close,secondary:true}],'LA PROVA DI '+c.genre.toUpperCase());}
function startPuzzle(c){clearPuzzleTimers();let index=0,busy=false;const p=panel('Una frase da ricordare.',`<p id="puzzleInfo">Ascolta i quattro suoni. Poi ripeti la sequenza.</p><div class="puzzle-sequence">${[0,1,2,3].map(i=>`<button class="puzzle-key" data-note="${i}" aria-label="Nota ${i+1}">${i+1}</button>`).join('')}</div><p class="fine" id="puzzleProgress">0 / 4</p>`,[{label:'Riascolta',run:play},{label:'Indizio visivo',run:()=>{p.querySelector('#puzzleInfo').textContent='Sequenza: '+c.pattern.map(n=>n+1).join(' → ');}},{label:'Torna fuori',run:close,secondary:true}],'ENIGMA MUSICALE / '+c.genre.toUpperCase());
 function flash(i){const b=p.querySelector(`[data-note="${i}"]`);b.classList.add('lit');try{audio.tone((c.root||110)*2*Math.pow(2,[0,4,7,12][i]/12),audio.ctx.currentTime,.3,'triangle',.14);}catch{}puzzleTimers.push(setTimeout(()=>b.classList.remove('lit'),260));}
 async function play(){if(busy)return;try{await audio.init();}catch{}busy=true;index=0;p.querySelector('#puzzleProgress').textContent='Ascolta…';c.pattern.forEach((n,i)=>puzzleTimers.push(setTimeout(()=>flash(n),i*550+150)));puzzleTimers.push(setTimeout(()=>{busy=false;p.querySelector('#puzzleProgress').textContent='Ora tocca a te · 0 / 4';},2500));}
 p.querySelectorAll('[data-note]').forEach(b=>b.onclick=async()=>{if(busy)return;try{await audio.init();}catch{}const n=Number(b.dataset.note);flash(n);if(n===c.pattern[index]){index++;p.querySelector('#puzzleProgress').textContent=index+' / 4';if(index===4){busy=true;if(!state.puzzles.includes(c.id)){state.puzzles.push(c.id);state.xp+=25;}save();updateJournal();puzzleTimers.push(setTimeout(()=>{clearPuzzleTimers();panel('La frase è completa.',`<p>${c.teacher}: «Ecco. Te lo porterai dietro anche nel prossimo pezzo.»</p><p>Ora puoi affrontare il concerto di ${c.name}.</p>`,[{label:'Verso il palco',run:close}],'PROVA SUPERATA');},500));}}else{index=0;p.querySelector('#puzzleProgress').textContent='Riprova dall’inizio. Puoi usare l’indizio.';}});play();}
function songBrief(id,kind){const inst=INSTRUMENTS[state.instrument],c=CITIES[id],short=kind==='tutorial';let title=short?'La prima prova insieme.':kind==='rival'?'Alta Tensione vi aspetta.':kind==='boat'?'Un palco in mezzo al mare.':kind==='home'?'Il concerto a casa.':kind==='final'?'Questa è la vostra estate.':`Suona a ${c.name}.`;
 const p=panel(title,`<p>${short?'Suona quando le note raggiungono la linea dorata. Le note lunghe vanno tenute premute fino alla fine.':kind==='rival'?'È il primo confronto della band. Il tuo punteggio è reale; i rivali vincono la valutazione complessiva prevista dal prologo.':kind==='final'?'Nico guarda Vale, poi guarda te. Il pubblico aspetta il primo accordo.':c.lesson||'La band è pronta. Adesso tocca a voi.'}</p><p><strong>${inst.name}</strong> · ${inst.role}<br>Tasti: <strong>${inst.labels.join(' · ')}</strong>. Su touch usa i pulsanti. ${state.instrument==='drums'?'D = cassa, F = rullante, J = charleston, K = piatto.':''}</p><label>Difficoltà <select id="songDifficulty"><option value="assist">Accessibile · soglia 35%</option><option value="normal">Normale · soglia 50%</option><option value="expert">Virtuoso · soglia 50%</option></select></label><p class="fine">Pausa con Spazio. Puoi uscire senza perdere i pass ottenuti.<br>${short?'Il tutorial introduce i comandi e può essere completato senza una soglia minima.':'Un errore non interrompe il brano. Puoi riprovare subito.'}</p>`,[{label:'Conta fino a quattro…',run:()=>{state.settings.difficulty=p.querySelector('select').value;save();startSong(id,kind);}},{label:'Non ancora',run:close,secondary:true}],'SALA PROVE / '+inst.name.toUpperCase());p.querySelector('select').value=state.settings.difficulty;}
async function startSong(id,kind){try{await audio.init();}catch{toast('Audio non disponibile. Puoi comunque seguire le note visive.');}close();mode='rhythm';const chart=makeChart(state.instrument,id,state.settings.difficulty,kind);song={...chart,kind,notes:chart.notes.map(n=>({...n,status:null,points:0})),start:audio.ctx?audio.ctx.currentTime+.15:performance.now()/1000+.15,nextBar:0,combo:0,maxCombo:0,feedback:'ASCOLTA IL CONTEGGIO',feedbackUntil:2,pressed:new Set(),paused:false,pauseAt:0,fallback:!audio.ctx,early:0};
 $('rhythmHud').hidden=false;$('laneControls').hidden=false;$('sceneBadge').hidden=true;$('songLabel').textContent=`${kind==='tutorial'?'TUTORIAL':kind==='final'?'FESTIVAL':CITIES[id].genre.toUpperCase()} / ${INSTRUMENTS[state.instrument].name.toUpperCase()}`;$('laneControls').innerHTML='';
 INSTRUMENTS[state.instrument].labels.forEach((key,lane)=>{const b=document.createElement('button');b.textContent=key;b.setAttribute('aria-label','Suona '+(state.instrument==='drums'?['cassa','rullante','charleston','piatto'][lane]:'corsia '+(lane+1)));b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);pressLane(lane);};const release=()=>releaseLane(lane);b.onpointerup=release;b.onpointercancel=release;$('laneControls').appendChild(b);});keys.clear();}
function now(){return song?.fallback?performance.now()/1000:audio.ctx?.currentTime||performance.now()/1000;}
function songTime(){return (song.paused?song.pauseAt:now())-song.start;}
function pressLane(lane){if(!song||song.paused||song.pressed.has(lane))return;song.pressed.add(lane);$('laneControls').children[lane]?.classList.add('pressed');const t=songTime()-state.settings.offset/1000,n=findNote(song.notes,lane,t,hitWindow(state.settings.difficulty));audio.note(state.instrument,lane,CITIES[song.city].root||110,audio.ctx?.currentTime||0,.12,.12);
 if(n){const error=Math.abs(n.t-t);n.status=n.duration?'holding':'hit';n.points=error<.065?1:error<.115?.85:.65;n.holdEnd=n.t+n.duration;song.combo++;song.maxCombo=Math.max(song.maxCombo,song.combo);song.feedback=error<.065?'PERFETTO':error<.115?'OTTIMO':'A TEMPO';song.feedbackUntil=songTime()+.65;}else if(t>1.5){song.combo=0;song.early++;song.feedback='CERCA IL TEMPO';song.feedbackUntil=songTime()+.45;}}
function releaseLane(lane){if(!song)return;song.pressed.delete(lane);$('laneControls').children[lane]?.classList.remove('pressed');for(const n of song.notes)if(n.lane===lane&&n.status==='holding'){if(songTime()<n.holdEnd-.1){n.points*=.5;song.combo=0;song.feedback='TIENI LA NOTA';song.feedbackUntil=songTime()+.6;}n.status='hit';}}
function pauseSong(){if(!song)return;if(!song.paused){song.pauseAt=now();song.paused=true;for(const lane of [...song.pressed])releaseLane(lane);audio.stop();panel('Un respiro prima del bis.',`<p>Il brano è in pausa. Riprendi quando sei pronto.</p>`,[{label:'Riprendi a suonare',run:()=>{song.start+=now()-song.pauseAt;song.paused=false;song.nextBar=Math.max(0,Math.ceil((songTime()-2)/(song.beat*4)));close();}},{label:'Ricomincia',run:()=>{const {city,kind}=song;exitSong(false);startSong(city,kind);}},{label:'Torna al viaggio',run:()=>exitSong()}],'PAUSA');}}
function exitSong(showToast=true){audio.stop();song=null;mode='world';$('rhythmHud').hidden=true;$('laneControls').hidden=true;$('sceneBadge').hidden=false;close();updateJournal();if(showToast)toast('Il viaggio riprende. Puoi tornare a suonare quando vuoi.');}
function endSong(){const completed=song;const score=Math.max(0,accuracy(completed.notes)-Math.floor(completed.early/3)),result=award(state,completed.city,score,completed.kind);exitSong(false);save();updateJournal();const actions=[{label:result.won?'Torna al viaggio':'Riprova',run:()=>{if(!result.won){songBrief(completed.city,completed.kind);return;}if(completed.kind==='boat')enterCity(9);close();}}];if(!result.won)actions.push({label:'Più tardi',run:close,secondary:true});
 panel(completed.kind==='final'&&result.won?'Ci chiedono il bis.':result.won?'Questo suono è vostro.':'Un’altra prova?',`<div class="result-number">${score}<span style="font-size:20px">%</span></div><p>${result.message}</p><p class="fine">Precisione ${accuracy(completed.notes)}% · Serie migliore ${completed.maxCombo}<br>Note fuori tempo: ${completed.early}</p>${completed.kind==='final'&&result.won?'<p>Le luci si accendono. Tra il pubblico ci sono facce incontrate lungo tutta l’estate. Nico ride: «Domani dove andiamo?»</p><p class="fine">Fine del percorso del prototipo. Le storie e i concerti potranno essere ampliati senza cambiare il salvataggio.</p>':''}`,actions,completed.kind==='final'?'SETTEMBRE / FINE DELLA PRIMA ESTATE':'DOPO IL CONCERTO');}
function tickSong(){if(!song||song.paused)return;const t=songTime();if(audio.ctx){while(song.nextBar<song.bars&&2+song.nextBar*song.beat*4<t+.25){audio.backing(song,CITIES[song.city],song.nextBar,song.start+2);song.nextBar++;}}
 const window=hitWindow(state.settings.difficulty);for(const n of song.notes){if(!n.status&&t-state.settings.offset/1000>n.t+window){n.status='miss';song.combo=0;}if(n.status==='holding'&&t>=n.holdEnd)n.status='hit';}
 $('scoreLabel').textContent=`${accuracy(song.notes.filter(n=>n.status))}% · ${song.combo} COMBO`;if(t>=song.duration)endSong();}
function showMap(){if(mode==='rhythm')return;const current=state.city;const p=panel('Le strade dell’estate.',`<p>Cammina lungo i sentieri per scoprire i luoghi nuovi. Dopo averli visitati, puoi tornarci direttamente dalla mappa.</p><div class="map-grid">${CITIES.map(c=>`<button class="map-city ${c.id===current?'current':''}" data-city="${c.id}" ${!state.visited.includes(c.id)?'disabled':''}><b>${c.id===current?'● ':''}${c.name}</b><small>${c.genre}${state.passes.includes(c.id)?' · PASS ✓':''}</small></button>`).join('')}</div><p class="fine">Da qui: ${neighbors(current).map(id=>CITIES[id].name).join(' · ')}<br>Il festival si apre con 8 pass e il concerto di ritorno a casa.</p>`,[{label:'Torna sulla strada',run:close}],'MAPPA / '+month(state));p.querySelectorAll('[data-city]').forEach(b=>b.onclick=()=>{if(state.stage!=='tour'){toast('Prima completa il pomeriggio in sala prove.');return;}const id=Number(b.dataset.city),reason=gate(state,id);if(reason){toast(reason);return;}enterCity(id);close();});}
function showBand(){if(mode==='rhythm')return;const missing=Object.keys(INSTRUMENTS).filter(id=>id!==state.instrument);panel('Ancora senza nome.',`<p>Una band nata in un garage. Il nome lo troveremo per strada.</p><div class="stat-row"><span>Tu</span><strong>${INSTRUMENTS[state.instrument].name}</strong></div><div class="stat-row"><span>Nico</span><strong>${INSTRUMENTS[missing[0]].name}</strong></div><div class="stat-row"><span>Vale</span><strong>${INSTRUMENTS[missing[1]].name}</strong></div><div class="stat-row"><span>Esperienza / livello</span><strong>${state.xp} / ${1+Math.floor(state.xp/100)}</strong></div><div class="stat-row"><span>Luoghi scoperti</span><strong>${state.visited.length} / 12</strong></div><div class="stat-row"><span>Ricordi</span><strong>${state.stories.includes(6)?'La cassetta del lato B':'Un’estate da riempire'}</strong></div><p class="fine">Nel prototipo il livello registra i traguardi. Le nuove meccaniche musicali arrivano nei brani, senza bonus che correggano gli errori.</p>`,[{label:'Torniamo fuori',run:close}],'LA NOSTRA BAND');}
function settings(){if(mode==='rhythm'){pauseSong();return;}const p=panel('Prima del prossimo pezzo.',`<label>Volume <input id="volume" type="range" min="0" max="1" step="0.05" value="${state.settings.volume}"></label><label>Correzione input: <span id="offsetValue">${state.settings.offset}</span> ms<input id="offset" type="range" min="-250" max="250" step="10" value="${state.settings.offset}"></label><p class="fine">Se devi premere dopo la nota visiva per seguire l’audio, aumenta il valore. La regolazione è manuale; usa la sala prove per verificarla.</p><label>Difficoltà <select id="difficulty"><option value="assist">Accessibile</option><option value="normal">Normale</option><option value="expert">Virtuoso</option></select></label><p class="fine">I salvataggi restano in questo browser. Esporta una copia per conservarli o spostarli.</p>`,[{label:'Salva e chiudi',run:()=>{save();close();}},{label:'Esporta partita',run:exportSave},{label:'Importa partita',run:importSave},{label:'Titolo',run:()=>{saved=validateState(state);welcome();},secondary:true}]);p.querySelector('#difficulty').value=state.settings.difficulty;p.querySelector('#volume').oninput=e=>{state.settings.volume=Number(e.target.value);syncAudio();};p.querySelector('#offset').oninput=e=>{state.settings.offset=Number(e.target.value);p.querySelector('#offsetValue').textContent=e.target.value;};p.querySelector('#difficulty').onchange=e=>{state.settings.difficulty=e.target.value;};}
function exportSave(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='una-estate-in-tour-salvataggio.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function importSave(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const valid=validateState(JSON.parse(await input.files[0].text()));if(!valid)throw Error();state=valid;syncAudio();setupTown();save();close();toast('Partita importata. Buon viaggio!');}catch{toast('Questo file non è un salvataggio valido.');}};input.click();}
function toggleBike(){if(mode!=='world'||!overlay.hidden)return;if(!state.bicycle){toast('Una vecchia bici ti aspetta a Binario Nord.');return;}state.bike=!state.bike;save();updateJournal();toast(state.bike?'In sella. La strada sembra più corta.':'Torni a camminare.');}

// Graphics: all tiles, characters and instruments are drawn locally, without sprite files.
function rect(x,y,w,h,color){ctx.fillStyle=color;ctx.fillRect(Math.round(x),Math.round(y),Math.ceil(w),Math.ceil(h));}
function text(s,x,y,color='#f4e8c8',size=10,align='left'){ctx.fillStyle=color;ctx.font=`${size}px monospace`;ctx.textAlign=align;ctx.fillText(s,Math.round(x),Math.round(y));ctx.textAlign='left';}
function hash(x,y){return Math.abs(Math.sin(x*127.1+y*311.7+state.city*19.3)*43758.5453)%1;}
function tree(x,y,size=1){ctx.save();ctx.translate(x,y);ctx.scale(size,size);rect(-18,0,39,10,'#183f3333');rect(-3,-16,7,22,'#82684b');rect(-19,-42,38,25,'#38644f');rect(-24,-32,48,23,'#35624b');rect(-14,-49,28,15,'#4d7a56');rect(-18,-30,12,8,'#558358');rect(7,-28,12,8,'#2b5444');rect(-8,-46,13,4,'#719260');ctx.restore();}
function character(x,y,color='#cf9368',variant=0,moving=false,bike=false){ctx.save();ctx.translate(Math.round(x),Math.round(y));const step=moving?Math.sin(walk*12)*3:0;rect(-8,0,19,5,'#183e3744');if(bike){rect(-15,0,10,8,'#364941');rect(7,0,10,8,'#364941');rect(-13,2,6,4,'#bcbba0');rect(9,2,6,4,'#bcbba0');rect(-7,-1,18,3,'#c2a868');}rect(-6,-4,5,7+step,'#394b54');rect(3,-4,5,7-step,'#394b54');rect(-8,-19,17,17,color);rect(-11,-17,4,11,'#d9ac86');rect(9,-17,4,11,'#d9ac86');rect(-5,-31,12,12,'#e2b991');rect(-7,-33,16,6,variant===1?'#a57848':'#483d38');rect(-7,-29,4,8,variant===1?'#a57848':'#483d38');rect(0,-25,2,2,'#353f37');rect(6,-25,2,2,'#353f37');if(variant===0){rect(-9,-36,19,5,'#c66d4b');rect(6,-32,7,3,'#c66d4b');rect(-5,-17,5,6,'#eadbb2');rect(4,-17,3,12,'#5e7564');}ctx.restore();}
function drawBuilding(b,c){const x=b.x*T,y=b.y*T,w=b.w*T,h=b.h*T;rect(x+7,y+12,w,h,'#214d3e2f');rect(x,y,w,h,'#e3d1a0');rect(x+5,y+30,w-10,h-30,'#dfcc9b');for(let i=0;i<w;i+=22)rect(x+i,y+38,1,h-38,'#cbb98e');rect(x-8,y-4,w+16,43,c.roof);rect(x-3,y-10,w+6,9,c.roof);rect(x+7,y-17,w-14,8,c.roof);for(let r=0;r<3;r++)for(let col=0;col<w/16;col++)rect(x+col*16+(r%2?8:0),y+r*12,13,2,'#f1c58c33');rect(x-8,y+37,w+16,6,'#725548');const doorx=x+w/2-10;rect(doorx,y+h-34,22,34,'#526b5c');rect(doorx+3,y+h-31,16,26,'#3c594e');rect(doorx+15,y+h-17,3,3,'#e9bd70');for(const wx of [x+20,x+w-42]){rect(wx,y+59,23,26,'#657d73');rect(wx+3,y+62,17,19,'#a8c7ba');rect(wx+10,y+61,3,23,'#e8d9ae');rect(wx+1,y+72,21,3,'#e8d9ae');rect(wx-2,y+84,27,4,'#8e7957');}text(b.label,x+w/2,y+h+14,'#335445',9,'center');}
function drawStage(x,y,genre){rect(x-64,y-60,140,64,'#806e56');rect(x-70,y-67,152,8,'#baa37a');rect(x-66,y-64,5,63,'#d1bc8f');rect(x+74,y-64,5,63,'#d1bc8f');rect(x-64,y-58,138,34,'#47675b');rect(x-59,y-55,128,2,'#d4b579');text(genre.toUpperCase(),x+5,y-37,'#ecd9ac',11,'center');for(let i=0;i<3;i++)rect(x-60,y-27+i*10,134,2,'#968267');rect(x-61,y-24,19,27,'#364f46');rect(x+51,y-24,19,27,'#364f46');rect(x-57,y-20,11,11,'#7d8771');rect(x+55,y-20,11,11,'#7d8771');rect(x-7,y-18,17,17,'#c29c6c');rect(x-3,y-14,9,9,'#6d7e69');rect(x-19,y-20,7,3,'#d4bb7c');rect(x+16,y-20,10,3,'#d4bb7c');}
function drawWorld(ts){const c=CITIES[state.city],isRoad=area==='road',maxX=isRoad?66:48,maxY=34;const camX=Math.max(0,Math.min(maxX*T-W,state.x*T-W/2)),camY=Math.max(0,Math.min(maxY*T-H,state.y*T-H/2));ctx.save();ctx.translate(-camX,-camY);rect(0,0,maxX*T,maxY*T,c.color);
 for(let y=0;y<maxY;y++)for(let x=0;x<maxX;x++){
  const rand=hash(x,y);const path=isRoad?(Math.abs(y-(20+Math.sin(x/7)*2))<2.3||x>20&&x<26&&y>15&&y<23):(y>=15&&y<=18||x>=21&&x<=25||x>=40&&y>=13&&y<=30||y>=24&&y<=26&&x>=10&&x<=39);
  if(path){rect(x*T,y*T,T,T,rand>.5?'#d6c493':'#d0be8c');if(rand>.74)rect(x*T+7,y*T+11,5,2,'#b8a97f');}
  else if(rand>.88){rect(x*T+5,y*T+8,2,5,'#3c6c4c66');rect(x*T+9,y*T+5,2,6,'#3c6c4c66');}else if(rand<.025&&y>10){rect(x*T+6,y*T+8,3,3,'#e3cf8b');rect(x*T+9,y*T+10,3,3,'#d99f7c');}
 }
 if(!isRoad){if([1,8,9].includes(state.city)){rect(0,27*T,19*T,7*T,'#669a9a');for(let i=0;i<28;i++){const x=hash(i,7)*440,y=27*T+hash(i,2)*165;rect(x+Math.sin(ts/1200+i)*5,y,15,2,'#b1c9ad77');}rect(17*T,27*T,4*T,7*T,'#d3c498');}else{for(let i=0;i<16;i++){rect(i*27+35,28*T,4,34,'#c7bb8b');rect(i*27+35,28*T+8,26,3,'#d3c599');rect(i*27+35,28*T+22,26,3,'#c9bc8a');}}
  objects.filter(o=>o.building).forEach(o=>drawBuilding(o.building,c));drawStage(35*T,20*T,state.city===0?'L’ESTATE COMINCIA QUI':c.genre);
  rect(22*T,14*T,34,24,'#6e7255');rect(22*T+3,14*T+3,28,18,'#e4d2a4');rect(22*T+7,14*T+7,10,7,'#b36d4d');rect(22*T+21,14*T+7,7,10,'#8b9b75');rect(22*T+4,15*T,3,15,'#74674c');rect(23*T+4,15*T,3,15,'#74674c');
  objects.filter(o=>o.kind==='exit').forEach(o=>{rect(o.x*T-7,o.y*T-22,5,26,'#836c50');rect(o.x*T-21,o.y*T-25,54,15,'#e2d0a4');text('→ '+CITIES[o.to].genre,o.x*T+5,o.y*T-14,'#4b6553',8,'center');});
 }else{rect(34*T,22*T,3,20,'#78674d');rect(34*T-15,22*T-10,54,16,'#e5c999');text(CITIES[road.to].genre.toUpperCase()+' →',34*T+12,22*T+1,'#5b6249',8,'center');}
 const forest=[];for(let x=0;x<maxX;x+=2){forest.push([x*T,4*T+hash(x,1)*50]);if(isRoad||x>22)forest.push([x*T,32*T+hash(x,2)*30]);}for(let y=7;y<30;y+=3){forest.push([T,y*T]);forest.push([(maxX-2)*T,y*T]);}if(isRoad)for(let x=10;x<60;x+=4){forest.push([x*T,(10+hash(x,3)*3)*T]);forest.push([x*T,(27+hash(x,4)*2)*T]);}
 forest.forEach(([x,y])=>tree(x,y,.9+hash(x,y)*.25));
 for(const o of objects){if(o.kind==='npc'||o.kind==='wanderer'){character(o.x*T,o.y*T,o.color,1);text(o.label,o.x*T,o.y*T-45,'#263f35',9,'center');if((c.type==='music'&&!state.puzzles.includes(c.id))||state.city===3&&!state.bicycle)text('!',o.x*T,o.y*T-56,'#fff0b7',20,'center');}if(o.kind==='sign'){rect(o.x*T,o.y*T-17,4,20,'#806b4c');rect(o.x*T-9,o.y*T-29,24,15,'#e0c493');text('♪',o.x*T+3,o.y*T-18,'#576747',10,'center');}}
 if(!isRoad&&state.city===0&&state.stage==='rival'){character(30*T,20*T,'#7b6c9b',1);character(31*T,20*T,'#647b94',1);text('ALTA TENSIONE',30.5*T,20*T-47,'#5b4a6c',9,'center');}
 character(state.x*T,state.y*T,'#d4a25f',0,keys.size>0||path.length>0,state.bike);if(path.length){const end=path[path.length-1];ctx.strokeStyle='#eed38b';ctx.lineWidth=2;ctx.strokeRect(end.x*T-6,end.y*T-6,12,12);}if(near){ctx.strokeStyle='#f4e8b6';ctx.lineWidth=2;ctx.strokeRect(near.x*T-15,near.y*T-42,30,47);}
 // Warm light and a restrained vignette, without external textures.
 ctx.restore();const gradient=ctx.createLinearGradient(0,0,W,H);gradient.addColorStop(0,'#fff1b10a');gradient.addColorStop(1,'#173d3020');ctx.fillStyle=gradient;ctx.fillRect(0,0,W,H);
}
function drawRhythm(ts){const s=song;if(!s)return;const t=songTime(),inst=INSTRUMENTS[state.instrument],lanes=inst.lanes,lw=80,left=(W-lanes*lw)/2,hitY=H-100,speed=175;
 rect(0,0,W,H,'#173c39');for(let i=0;i<12;i++){const x=35+i*84;rect(x,90,2,300,'#284d44');rect(x-20,90,40,3,'#3e5a49');}rect(0,380,W,220,'#21463b');for(let i=0;i<15;i++)rect(0,390+i*13,W,2,'#2b5041');drawStage(W/2,370,'LA NOSTRA BAND');character(132,350,'#d4a25f',0);character(820,350,'#b16b60',1);
 for(let l=0;l<lanes;l++){rect(left+l*lw,68,lw-2,H-125,'#0b272ae8');rect(left+l*lw,68,1,H-125,'#50745b55');if(s.pressed.has(l))rect(left+l*lw+3,hitY-15,lw-8,30,inst.colors[l]+'77');text(inst.labels[l],left+l*lw+lw/2,hitY+34,inst.colors[l],17,'center');}
 ctx.save();ctx.beginPath();ctx.rect(left,65,lanes*lw,H-135);ctx.clip();for(let i=Math.max(0,Math.floor((t-4)/s.beat));i<(t+4)/s.beat;i++){const y=hitY-(2+i*s.beat-t)*speed;rect(left,y,lanes*lw,1,i%4===0?'#8ea27d55':'#617b5b22');}
 for(const n of s.notes){if(n.status==='hit'||n.status==='miss')continue;const y=hitY-(n.t-t)*speed;if(y<-200||y>H+150)continue;const x=left+n.lane*lw+9,col=inst.colors[n.lane];if(n.duration){rect(x+23,y-n.duration*speed,14,n.duration*speed,col+'99');rect(x+27,y-n.duration*speed,6,n.duration*speed,'#f7eac555');}if(n.status!=='holding'){rect(x,y-7,lw-20,15,col);rect(x+3,y-7,lw-26,3,'#ffefb688');}}
 ctx.restore();rect(left-7,hitY,lanes*lw+12,3,'#f3c76f');text('TOCCA QUI A TEMPO',W/2,hitY-13,'#d6c492',8,'center');
 if(t<2){text(String(Math.max(1,4-Math.floor(t/.5))),W/2,235,'#f0d49a',75,'center');text('UNO, DUE…',W/2,275,'#d4c591',12,'center');}else if(t<s.feedbackUntil){text(s.feedback,W/2,135,'#f3d890',16,'center');}
 text(s.combo>1?`${s.combo} ×`:'TROVA IL TUO RITMO',W/2,190,'#dfd0a7',s.combo>1?32:10,'center');rect(0,H-3,W*Math.min(1,t/s.duration),3,'#f1c673');text(`${Math.max(0,Math.ceil(s.duration-t))} s`,W-24,H-20,'#ced7b7',10,'right');}
function canMove(x,y){const max=area==='road'?64:45;if(x<2.5||x>max||y<8||y>30.5)return false;for(const b of solids)if(x>b.x-.4&&x<b.x+b.w+.4&&y>b.y-.2&&y<b.y+b.h+.25)return false;return !(area==='town'&&[1,8,9].includes(state.city)&&x<19&&y>27);}
let saveClock=0;
function update(dt){if(mode==='rhythm'){tickSong();return;}if(!overlay.hidden)return;let dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),dy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);if(dx||dy){path=[];tapObject=null;}else if(path.length){const next=path[0],dist=Math.hypot(next.x-state.x,next.y-state.y);if(dist<.14){path.shift();if(!path.length&&tapObject){near=tapObject;tapObject=null;interact();return;}}else{dx=(next.x-state.x)/dist;dy=(next.y-state.y)/dist;}}
 if(dx||dy){const length=Math.hypot(dx,dy),speed=state.bike?8:4.2;dx=dx/length*dt*speed;dy=dy/length*dt*speed;if(canMove(state.x+dx,state.y))state.x+=dx;if(canMove(state.x,state.y+dy))state.y+=dy;walk+=dt;saveClock+=dt;if(saveClock>3){saveClock=0;if(area==='town')save();}}
 near=null;let best=2.4;for(const o of objects){const dist=Math.hypot(o.x-state.x,o.y-state.y);if(dist<best){best=dist;near=o;}}$('prompt').hidden=!near;if(near)$('prompt').textContent='E / USA · '+near.label;
}
function frame(ts){const dt=Math.min(.045,(ts-last)/1000);last=ts;update(dt);ctx.clearRect(0,0,W,H);if(mode==='rhythm')drawRhythm(ts);else drawWorld(ts);requestAnimationFrame(frame);}
document.addEventListener('keydown',e=>{const key=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(key)&&!['INPUT','SELECT'].includes(e.target.tagName))e.preventDefault();if(e.repeat)return;if(mode==='rhythm'){if(key===' '){if(song?.paused){overlay.querySelector('button')?.click();}else pauseSong();return;}if(!overlay.hidden)return;const lane=INSTRUMENTS[state.instrument].labels.map(k=>k.toLowerCase()).indexOf(key);if(lane>=0)pressLane(lane);return;}if(!overlay.hidden){if(key==='escape'&&state.stage)close();return;}if(key==='e'||key==='enter')interact();else if(key==='b')toggleBike();else if(key==='m')showMap();else if(key==='escape')settings();else keys.add(key);});
document.addEventListener('keyup',e=>{keys.delete(e.key.toLowerCase());if(mode==='rhythm'){const lane=INSTRUMENTS[state.instrument].labels.map(k=>k.toLowerCase()).indexOf(e.key.toLowerCase());if(lane>=0)releaseLane(lane);}});
window.addEventListener('blur',()=>{keys.clear();if(song&&!song.paused)pauseSong();});document.addEventListener('visibilitychange',()=>{if(document.hidden){keys.clear();if(song&&!song.paused)pauseSong();if(mode==='world'&&area==='town')save();}});
document.querySelectorAll('[data-move]').forEach(b=>{const k={up:'arrowup',down:'arrowdown',left:'arrowleft',right:'arrowright'}[b.dataset.move];b.onpointerdown=e=>{if(!overlay.hidden||mode!=='world')return;e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(k);};b.onpointerup=b.onpointercancel=()=>keys.delete(k);});
$('touchAction').onclick=interact;$('touchBike').onclick=toggleBike;$('mapBtn').onclick=showMap;$('bandBtn').onclick=showBand;$('settingsBtn').onclick=settings;$('pauseSong').onclick=pauseSong;$('exitSong').onclick=()=>exitSong();$('soundBtn').onclick=()=>{state.settings.muted=!state.settings.muted;syncAudio();save();};
